  1→import { NextResponse } from "next/server";
  2→import type { NextRequest } from "next/server";
  3→import { supportedLanguages, defaultLanguage, type Language } from "./app/lib/i18n";
  4→
  5→// Browser language to supported language mapping
  6→const browserLangMap: Record<string, Language> = {
  7→  // Russian Federation - 26%
  8→  ru: "ru",
  9→  "ru-RU": "ru",
 10→  // Japan - 17%
 11→  ja: "ja",
 12→  "ja-JP": "ja",
 13→  // USA / English - 15%
 14→  en: "en",
 15→  "en-US": "en",
 16→  "en-GB": "en",
 17→  "en-AU": "en",
 18→  "en-CA": "en",
 19→  // South Korea - 11%
 20→  ko: "ko",
 21→  "ko-KR": "ko",
 22→  // Netherlands - 7%
 23→  nl: "nl",
 24→  "nl-NL": "nl",
 25→  "nl-BE": "nl",
 26→  // Germany - 3%
 27→  de: "de",
 28→  "de-DE": "de",
 29→  "de-AT": "de",
 30→  "de-CH": "de",
 31→  // Chinese
 32→  zh: "zh",
 33→  "zh-CN": "zh",
 34→  "zh-TW": "zh",
 35→  "zh-HK": "zh",
 36→  // French
 37→  fr: "fr",
 38→  "fr-FR": "fr",
 39→  "fr-CA": "fr",
 40→  "fr-BE": "fr",
 41→  "fr-CH": "fr",
 42→  // Spanish
 43→  es: "es",
 44→  "es-ES": "es",
 45→  "es-MX": "es",
 46→  "es-AR": "es",
 47→  // Italian
 48→  it: "it",
 49→  "it-IT": "it",
 50→  // Portuguese
 51→  pt: "pt",
 52→  "pt-BR": "pt",
 53→  "pt-PT": "pt",
 54→  // Arabic
 55→  ar: "ar",
 56→  "ar-SA": "ar",
 57→  "ar-AE": "ar",
 58→  "ar-EG": "ar",
 59→  // Hindi
 60→  hi: "hi",
 61→  "hi-IN": "hi",
 62→};
 63→
 64→function getPreferredLanguage(request: NextRequest): Language {
 65→  // Check Accept-Language header
 66→  const acceptLanguage = request.headers.get("accept-language");
 67→  if (acceptLanguage) {
 68→    const languages = acceptLanguage
 69→      .split(",")
 70→      .map((lang) => {
 71→        const [code, priority] = lang.trim().split(";q=");
 72→        return {
 73→          code: code.trim(),
 74→          priority: priority ? parseFloat(priority) : 1,
 75→        };
 76→      })
 77→      .sort((a, b) => b.priority - a.priority);
 78→
 79→    for (const { code } of languages) {
 80→      // Try exact match first
 81→      if (browserLangMap[code]) {
 82→        return browserLangMap[code];
 83→      }
 84→      // Try language code without region
 85→      const langCode = code.split("-")[0];
 86→      if (browserLangMap[langCode]) {
 87→        return browserLangMap[langCode];
 88→      }
 89→    }
 90→  }
 91→
 92→  return defaultLanguage;
 93→}
 94→
 95→export function middleware(request: NextRequest) {
 96→  const { pathname } = request.nextUrl;
 97→
 98→  // Skip for static files, API routes, and Next.js internals
 99→  if (
100→    pathname.startsWith("/_next") ||
101→    pathname.startsWith("/api") ||
102→    pathname.includes(".") ||
103→    pathname === "/favicon.ico" ||
104→    pathname === "/robots.txt" ||
105→    pathname === "/sitemap.xml"
106→  ) {
107→    return NextResponse.next();
108→  }
109→
110→  // Check if pathname already has a valid language prefix
111→  const pathnameSegments = pathname.split("/").filter(Boolean);
112→  const firstSegment = pathnameSegments[0];
113→
114→  if (firstSegment && supportedLanguages.includes(firstSegment as Language)) {
115→    // Language is already in the path, continue
116→    return NextResponse.next();
117→  }
118→
119→  // Handle legacy query parameter URLs (redirect to new path-based URLs)
120→  const langParam = request.nextUrl.searchParams.get("lang");
121→  if (langParam && supportedLanguages.includes(langParam as Language)) {
122→    const newUrl = new URL(`/${langParam}`, request.url);
123→    return NextResponse.redirect(newUrl, { status: 301 });
124→  }
125→
126→  // Root path or path without language - redirect to appropriate language
127→  if (pathname === "/" || !firstSegment) {
128→    const preferredLanguage = getPreferredLanguage(request);
129→    const newUrl = new URL(`/${preferredLanguage}`, request.url);
130→    return NextResponse.redirect(newUrl, { status: 307 });
131→  }
132→
133→  // For other paths without language prefix, redirect to default language
134→  const preferredLanguage = getPreferredLanguage(request);
135→  const newUrl = new URL(`/${preferredLanguage}${pathname}`, request.url);
136→  return NextResponse.redirect(newUrl, { status: 307 });
137→}
138→
139→export const config = {
140→  matcher: [
141→    // Match all paths except static files and API
142→    "/((?!_next/static|_next/image|favicon.ico|.*\\..*|api).*)",
143→  ],
144→};
