 1→import type { Metadata } from "next";
 2→import { Geist, Geist_Mono } from "next/font/google";
 3→import "../globals.css";
 4→import { Analytics } from "@vercel/analytics/react";
 5→import {
 6→  Language,
 7→  supportedLanguages,
 8→  isValidLanguage,
 9→  defaultLanguage,
10→} from "../lib/i18n";
11→import {
12→  generateMetadataForLanguage,
13→  generateStructuredDataForLanguage,
14→  getLanguageCode,
15→  languageMetadata,
16→} from "../lib/metadata";
17→
18→const geistSans = Geist({
19→  variable: "--font-geist-sans",
20→  subsets: ["latin"],
21→});
22→
23→const geistMono = Geist_Mono({
24→  variable: "--font-geist-mono",
25→  subsets: ["latin"],
26→});
27→
28→type Props = {
29→  params: Promise<{ lang: string }>;
30→  children: React.ReactNode;
31→};
32→
33→export async function generateStaticParams() {
34→  return supportedLanguages.map((lang) => ({ lang }));
35→}
36→
37→export async function generateMetadata({ params }: Props): Promise<Metadata> {
38→  const { lang } = await params;
39→  const validLang: Language = isValidLanguage(lang) ? lang : defaultLanguage;
40→  return generateMetadataForLanguage(validLang);
41→}
42→
43→export default async function LangLayout({ children, params }: Props) {
44→  const { lang } = await params;
45→  const validLang: Language = isValidLanguage(lang) ? lang : defaultLanguage;
46→
47→  const structuredData = generateStructuredDataForLanguage(validLang);
48→  const langCode = getLanguageCode(validLang);
49→
50→  return (
51→    <html lang={langCode} className={`${geistSans.variable} ${geistMono.variable}`}>
52→      <head>
53→        <link rel="alternate" hrefLang="x-default" href="https://pdf2md.app/en" />
54→        {supportedLanguages.map((supportedLang) => {
55→          const meta = languageMetadata[supportedLang];
56→          return (
57→            <link
58→              key={meta.hrefLang}
59→              rel="alternate"
60→              hrefLang={meta.hrefLang}
61→              href={`https://pdf2md.app${meta.canonicalPath}`}
62→            />
63→          );
64→        })}
65→        <script
66→          type="application/ld+json"
67→          dangerouslySetInnerHTML={{
68→            __html: JSON.stringify(structuredData),
69→          }}
70→        />
71→      </head>
72→      <body className="antialiased overflow-hidden">
73→        {children}
74→        <Analytics />
75→      </body>
76→    </html>
77→  );
78→}
