  1→"use client";
  2→
  3→import { useState, useRef, useEffect } from "react";
  4→import { processPdfWithMistral, processImageWithMistral } from "../action/mistral";
  5→import { OCRResponse } from "@mistralai/mistralai/src/models/components/ocrresponse.js";
  6→import OcrResultView from "../components/OcrResultView";
  7→import UploadResult from "../components/UploadResult";
  8→import Header from "../components/Header";
  9→import { useDropzone } from "react-dropzone";
 10→import Footer from "../components/Footer";
 11→import { useParams } from "next/navigation";
 12→import {
 13→  getTranslations,
 14→  formatTranslation,
 15→  isValidLanguage,
 16→  defaultLanguage,
 17→  type Language,
 18→} from "../lib/i18n";
 19→import { downloadAsZip } from "../action/downloadHelper";
 20→import { Copy, Check } from "lucide-react";
 21→
 22→export default function FileUploader() {
 23→  const params = useParams();
 24→  const langParam = params.lang as string;
 25→  const lang: Language = isValidLanguage(langParam) ? langParam : defaultLanguage;
 26→  const t = getTranslations(lang);
 27→
 28→  const [file, setFile] = useState<File | null>(null);
 29→  const [localFileUrl, setLocalFileUrl] = useState<string | null>(null);
 30→  const [processing, setProcessing] = useState(false);
 31→  const [uploadResult, setUploadResult] = useState<{
 32→    success: boolean;
 33→    url?: string;
 34→    fileType?: "pdf" | "image";
 35→    errorMessage?: string;
 36→  } | null>(null);
 37→  const [ocrResult, setOcrResult] = useState<
 38→    OCRResponse | { success: false; error: string } | null
 39→  >(null);
 40→  const fileInputRef = useRef<HTMLInputElement>(null);
 41→  const [currentStep, setCurrentStep] = useState<"upload" | "analyze" | "result">("upload");
 42→  const [activeTab, setActiveTab] = useState<"preview" | "result" | "text">("preview");
 43→  const [isDownloading, setIsDownloading] = useState(false);
 44→  const [copyingAll, setCopyingAll] = useState(false);
 45→  const [copyingPage, setCopyingPage] = useState<number | null>(null);
 46→
 47→  // Supported file types
 48→  const acceptedFileTypes = {
 49→    "application/pdf": [".pdf"],
 50→  };
 51→
 52→  // Check if file type is valid
 53→  const isValidFileType = (file: File): boolean => {
 54→    return file.type === "application/pdf";
 55→  };
 56→
 57→  // Check if file size is valid (under 20MB)
 58→  const isValidFileSize = (file: File): boolean => {
 59→    const MAX_FILE_SIZE = 20 * 1024 * 1024; // 20MB in bytes
 60→    return file.size <= MAX_FILE_SIZE;
 61→  };
 62→
 63→  // Get file type
 64→  const getFileType = (file: File): "pdf" | null => {
 65→    if (file.type === "application/pdf") return "pdf";
 66→    return null;
 67→  };
 68→
 69→  const onDrop = (acceptedFiles: File[]) => {
 70→    if (acceptedFiles && acceptedFiles.length > 0) {
 71→      const newFile = acceptedFiles[0];
 72→      if (!isValidFileType(newFile)) {
 73→        alert(t.onlyPdfFiles);
 74→        return;
 75→      }
 76→
 77→      if (!isValidFileSize(newFile)) {
 78→        alert(t.fileSizeExceeded);
 79→        return;
 80→      }
 81→
 82→      setFile(newFile);
 83→      setUploadResult(null);
 84→      setOcrResult(null);
 85→      handleProcess(newFile);
 86→    }
 87→  };
 88→
 89→  const { getRootProps, getInputProps, isDragActive } = useDropzone({
 90→    onDrop,
 91→    accept: acceptedFileTypes,
 92→    maxFiles: 1,
 93→    noClick: false,
 94→    noKeyboard: false,
 95→  });
 96→
 97→  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
 98→    if (e.target.files && e.target.files.length > 0) {
 99→      const selectedFile = e.target.files[0];
100→      if (!isValidFileType(selectedFile)) {
101→        alert(t.onlyPdfFiles);
102→        return;
103→      }
104→
105→      if (!isValidFileSize(selectedFile)) {
106→        alert(t.fileSizeExceeded);
107→        return;
108→      }
109→
110→      setFile(selectedFile);
111→      setUploadResult(null);
112→      setOcrResult(null);
113→      handleProcess(selectedFile);
114→    }
115→  };
116→
117→  // Convert File to Base64
118→  const fileToBase64 = (file: File): Promise<string> => {
119→    return new Promise((resolve, reject) => {
120→      const reader = new FileReader();
121→      reader.readAsDataURL(file);
122→      reader.onload = () => {
123→        const result = reader.result as string;
124→        // Remove data URL prefix (e.g., "data:application/pdf;base64,")
125→        const base64 = result.split(",")[1];
126→        resolve(base64);
127→      };
128→      reader.onerror = (error) => reject(error);
129→    });
130→  };
131→
132→  const handleProcess = async (selectedFile?: File) => {
133→    const fileToProcess = selectedFile || file;
134→    if (!fileToProcess) return;
135→
136→    setProcessing(true);
137→    setUploadResult(null);
138→    setOcrResult(null);
139→    setCurrentStep("analyze");
140→    // 分析開始時からmarkdownタブを表示
141→    setActiveTab("result");
142→
143→    // Create local URL for preview
144→    const objectUrl = URL.createObjectURL(fileToProcess);
145→    setLocalFileUrl(objectUrl);
146→
147→    try {
148→      const fileType = getFileType(fileToProcess);
149→      if (!fileType) {
150→        throw new Error("Unsupported file format");
151→      }
152→
153→      // Set upload result for preview
154→      setUploadResult({
155→        success: true,
156→        url: objectUrl,
157→        fileType: fileType,
158→      });
159→
160→      // Convert file to base64
161→      const base64Data = await fileToBase64(fileToProcess);
162→
163→      let response;
164→
165→      if (fileType === "pdf") {
166→        // PDF: Upload to S3, process OCR, then delete
167→        response = await processPdfWithMistral(base64Data, fileToProcess.name, true);
168→      } else {
169→        // Image: Process directly with Base64 Data URL (no storage needed)
170→        response = await processImageWithMistral(base64Data, fileToProcess.type, true);
171→      }
172→
173→      if (response.error) {
174→        throw response.error;
175→      }
176→
177→      if (response.result) {
178→        console.log(`${fileType === "pdf" ? t.pdf : t.image} analysis result:`, response.result);
179→        setOcrResult(response.result);
180→        setCurrentStep("result");
181→      }
182→
183→      if (fileInputRef.current) {
184→        fileInputRef.current.value = "";
185→      }
186→    } catch (error) {
187→      console.error("Processing error:", error);
188→      setUploadResult({
189→        success: false,
190→        errorMessage: error instanceof Error ? error.message : undefined,
191→      });
192→      setOcrResult({
193→        success: false,
194→        error:
195→          error instanceof Error
196→            ? `${t.analysisError}: ${error.message}`
197→            : t.analysisError,
198→      });
199→    } finally {
200→      setProcessing(false);
201→    }
202→  };
203→
204→  // OCR結果が設定されたらmarkdownタブに切り替え
205→  useEffect(() => {
206→    if (ocrResult && !processing) {
207→      setActiveTab("result");
208→    }
209→  }, [ocrResult, processing]);
210→
211→  // クリップボードにコピーする関数（個別ページ用）
212→  const copyToClipboard = async (text: string, pageIndex?: number | null) => {
213→    try {
214→      await navigator.clipboard.writeText(text);
215→
216→      if (pageIndex !== undefined && pageIndex !== null) {
217→        // 個別ページコピーの場合
218→        setCopyingPage(pageIndex);
219→        setTimeout(() => {
220→          setCopyingPage(null);
221→        }, 3000);
222→      }
223→    } catch (err) {
224→      console.error("Copy failed:", err);
225→    }
226→  };
227→
228→  // すべてのページのマークダウンを結合してコピーする関数
229→  const copyAllMarkdown = async () => {
230→    if (!ocrResult || "error" in ocrResult || !ocrResult.pages) return;
231→
232→    const allMarkdown = ocrResult.pages
233→      .map((page) => {
234→        const pageTitle = `# ${formatTranslation(t.pageIndicator, {
235→          current: page.index + 1,
236→          total: ocrResult.pages?.length ?? 0,
237→        })}\n\n`;
238→        return pageTitle + (page.markdown || t.noTextOnPage);
239→      })
240→      .join("\n\n---\n\n");
241→
242→    try {
243→      await navigator.clipboard.writeText(allMarkdown);
244→      setCopyingAll(true);
245→      setTimeout(() => {
246→        setCopyingAll(false);
247→      }, 3000);
248→    } catch (err) {
249→      console.error("Copy failed:", err);
250→    }
251→  };
252→
253→  // ZIPファイルとしてダウンロードする関数
254→  const handleDownloadZip = async () => {
255→    if (!ocrResult || "error" in ocrResult || !ocrResult.pages) return;
256→
257→    try {
258→      setIsDownloading(true);
259→      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").substring(0, 19);
260→      await downloadAsZip(ocrResult, `ocr-export-${timestamp}`);
261→    } catch (error) {
262→      console.error("ZIP download failed:", error);
263→    } finally {
264→      setIsDownloading(false);
265→    }
266→  };
267→
268→  // マークダウンのみをダウンロードする関数
269→  const handleDownloadMarkdown = async () => {
270→    if (!ocrResult || "error" in ocrResult || !ocrResult.pages) return;
271→
272→    try {
273→      setIsDownloading(true);
274→      const timestamp = new Date().toISOString().replace(/[:.]/g, "-").substring(0, 19);
275→      await downloadAsZip(ocrResult, `ocr-markdown-${timestamp}`, true);
276→    } catch (error) {
277→      console.error("Markdown download failed:", error);
278→    } finally {
279→      setIsDownloading(false);
280→    }
281→  };
282→
283→  const handleReset = () => {
284→    // Clean up object URL to prevent memory leaks
285→    if (localFileUrl) {
286→      URL.revokeObjectURL(localFileUrl);
287→    }
288→    setFile(null);
289→    setLocalFileUrl(null);
290→    setUploadResult(null);
291→    setOcrResult(null);
292→    setCurrentStep("upload");
293→    setActiveTab("preview");
294→    setIsDownloading(false);
295→    setCopyingAll(false);
296→  };
297→
298→  // Initial upload state
299→  if (currentStep === "upload" && !file) {
300→    return (
301→      <div className="flex flex-col w-full h-screen">
302→        <Header isInitialUpload={true} translations={t} />
303→
304→        <div
305→          {...getRootProps()}
306→          className={`flex-1 flex flex-col items-center justify-center p-8 mt-[10px] mr-[10px] ml-[10px] mb-[10px] border-2 border-dashed rounded-xl transition-all duration-200 ${
307→            isDragActive
308→              ? "border-blue-500 bg-blue-50"
309→              : "border-gray-300 bg-gray-50 hover:border-orange-400 hover:bg-orange-50"
310→          } cursor-pointer`}
311→          onClick={() => fileInputRef.current?.click()}
312→        >
313→          <input {...getInputProps()} ref={fileInputRef} onChange={handleFileChange} />
314→          <div className="text-center space-y-4">
315→            <h2 className="text-xl font-semibold text-gray-700">
316→              {isDragActive ? t.dropHereText : t.dragDropText}
317→            </h2>
318→
319→            <p className="text-gray-500 max-w-md mx-auto">
320→              {t.dragDropSubtext}
321→              <span className="block text-xs mt-1">{t.dragDropNote}</span>
322→            </p>
323→
324→            <button
325→              type="button"
326→              className="mt-2 inline-flex items-center px-4 py-2 bg-orange-500 hover:bg-orange-600 text-white rounded-2xl shadow-sm transition-colors"
327→              onClick={(e) => {
328→                e.stopPropagation();
329→                fileInputRef.current?.click();
330→              }}
331→            >
332→              {t.selectFileButton}
333→            </button>
334→          </div>
335→        </div>
336→        <Footer translations={t} />
337→      </div>
338→    );
339→  }
340→
341→  // Upload, analysis, or result display state
342→  return (
343→    <div className="flex flex-col h-screen w-full bg-gray-50">
344→      <Header
345→        currentStep={currentStep}
346→        onReset={handleReset}
347→        translations={t}
348→        activeTab={activeTab}
349→        onTabChange={setActiveTab}
350→        ocrResult={ocrResult}
351→        onCopyAll={copyAllMarkdown}
352→        onDownloadZip={handleDownloadZip}
353→        onDownloadMarkdown={handleDownloadMarkdown}
354→        isDownloading={isDownloading}
355→        copyingAll={copyingAll}
356→      />
357→
358→      {/* Main content: 2-column layout */}
359→      <div className="flex-1 flex flex-col md:flex-row overflow-hidden">
360→        {/* Left side: File preview */}
361→        <div
362→          className={`w-full md:w-1/2 p-0 md:p-2 overflow-y-auto overflow-x-hidden bg-gray-100 border-r border-gray-200 ${
363→            activeTab === "preview" ? "block h-full" : "hidden md:block"
364→          }`}
365→        >
366→          {uploadResult?.url ? (
367→            <div className="h-full flex flex-col">
368→              <div className="flex items-center justify-between px-2 py-1 bg-white border-b border-gray-200">
369→                <h2 className="text-xs font-semibold text-gray-700 truncate">
370→                  {file?.name || t.uploadedFile}
371→                </h2>
372→                {file && (
373→                  <span className="text-[10px] text-gray-500 bg-gray-100 px-1.5 py-0.5 rounded">
374→                    {(file.size / 1024 / 1024).toFixed(2)} MB
375→                  </span>
376→                )}
377→              </div>
378→              <div className="flex-1 relative bg-gray-200 overflow-hidden">
379→                {uploadResult.fileType === "pdf" ? (
380→                  <iframe
381→                    src={uploadResult.url}
382→                    className="w-full h-full border-0"
383→                    title={t.pdf}
384→                  ></iframe>
385→                ) : (
386→                  <div className="w-full h-full flex items-center justify-center">
387→                    <img
388→                      src={uploadResult.url}
389→                      alt={t.image}
390→                      className="max-w-full max-h-full object-contain"
391→                    />
392→                  </div>
393→                )}
394→              </div>
395→            </div>
396→          ) : (
397→            <div className="h-full flex items-center justify-center text-gray-500">
398→              {processing && !uploadResult?.url ? (
399→                <div className="text-center">
400→                  <svg
401→                    className="animate-spin h-8 w-8 text-orange-500 mx-auto mb-2"
402→                    xmlns="http://www.w3.org/2000/svg"
403→                    fill="none"
404→                    viewBox="0 0 24 24"
405→                  >
406→                    <circle
407→                      className="opacity-25"
408→                      cx="12"
409→                      cy="12"
410→                      r="10"
411→                      stroke="currentColor"
412→                      strokeWidth="4"
413→                    ></circle>
414→                    <path
415→                      className="opacity-75"
416→                      fill="currentColor"
417→                      d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"
418→                    ></path>
