  1→"use client";
  2→
  3→import { OCRResponse } from "@mistralai/mistralai/src/models/components/ocrresponse.js";
  4→import { OCRPageObject } from "@mistralai/mistralai/src/models/components/ocrpageobject.js";
  5→import { OCRImageObject } from "@mistralai/mistralai/src/models/components/ocrimageobject.js";
  6→import JSZip from "jszip";
  7→import { saveAs } from "file-saver";
  8→
  9→/**
 10→ * Function to download markdown files and images as a ZIP archive
 11→ * @param ocrResult OCR result object
 12→ * @param fileName Name of the downloaded ZIP file (without extension)
 13→ * @param markdownOnly If true, only download the markdown file
 14→ */
 15→export async function downloadAsZip(
 16→  ocrResult: OCRResponse,
 17→  fileName: string = "ocr-export",
 18→  markdownOnly: boolean = false
 19→): Promise<void> {
 20→  // Argument validation
 21→  if (!ocrResult || !ocrResult.pages || ocrResult.pages.length === 0) {
 22→    throw new Error("No valid OCR results available");
 23→  }
 24→
 25→  try {
 26→    // Markdown file combining all pages
 27→    let allMarkdown = "";
 28→
 29→    // Loop through each page to combine markdown
 30→    ocrResult.pages.forEach((page: OCRPageObject) => {
 31→      // Add page's markdown
 32→      if (page.markdown) {
 33→        // Add to the combined markdown
 34→        allMarkdown += page.markdown + "\n\n";
 35→      }
 36→    });
 37→
 38→    // If downloading markdown only
 39→    if (markdownOnly) {
 40→      const blob = new Blob([allMarkdown], { type: "text/markdown;charset=utf-8" });
 41→      saveAs(blob, `${fileName}.md`);
 42→      return Promise.resolve();
 43→    }
 44→
 45→    // Process for combining markdown and images into a ZIP
 46→    // Create JSZip instance
 47→    const zip = new JSZip();
 48→
 49→    // Loop through each page to add markdown and images
 50→    ocrResult.pages.forEach((page: OCRPageObject) => {
 51→      // Add images included in the page to the ZIP
 52→      if (page.images && page.images.length > 0) {
 53→        page.images.forEach((image: OCRImageObject) => {
 54→          if (image.imageBase64) {
 55→            try {
 56→              // Extract Base64 data
 57→              let base64Data = image.imageBase64;
 58→              let contentType = "image/png"; // Default
 59→
 60→              // Extract Base64 part and MIME type directly from data URL
 61→              if (base64Data.startsWith("data:")) {
 62→                const parts = base64Data.split(",");
 63→                const matches = parts[0].match(/^data:(.+);base64$/);
 64→                if (matches && matches.length > 1) {
 65→                  contentType = matches[1];
 66→                  base64Data = parts[1];
 67→                }
 68→              }
 69→
 70→              // Determine image extension
 71→              const extension = getExtensionFromMimeType(contentType);
 72→
 73→              // Convert to binary data
 74→              const binaryData = atob(base64Data);
 75→              const bytes = new Uint8Array(binaryData.length);
 76→              for (let i = 0; i < binaryData.length; i++) {
 77→                bytes[i] = binaryData.charCodeAt(i);
 78→              }
 79→
 80→              // Use image ID as filename (or random string if ID is not available)
 81→              const imageFileName =
 82→                image.id || `image-${Math.random().toString(36).substring(2, 10)}${extension}`;
 83→              zip.file(imageFileName, bytes.buffer, { binary: true });
 84→            } catch (error) {
 85→              console.error(`Image processing error: ${error}`);
 86→            }
 87→          }
 88→        });
 89→      }
 90→    });
 91→
 92→    // Add the combined markdown of all pages to the ZIP
 93→    zip.file("main.md", allMarkdown);
 94→
 95→    // Generate ZIP file
 96→    const zipBlob = await zip.generateAsync({ type: "blob" });
 97→
 98→    // Download ZIP file
 99→    saveAs(zipBlob, `${fileName}.zip`);
100→
101→    return Promise.resolve();
102→  } catch (error) {
103→    console.error("Error occurred while generating ZIP file:", error);
104→    return Promise.reject(error);
105→  }
106→}
107→
108→/**
109→ * Get appropriate file extension from MIME type
110→ */
111→function getExtensionFromMimeType(mimeType: string): string {
112→  const mimeToExt: { [key: string]: string } = {
113→    "image/jpeg": ".jpg",
114→    "image/jpg": ".jpg",
115→    "image/png": ".png",
116→  };
117→
118→  return mimeToExt[mimeType] || ".png"; // Default is PNG
119→}
