118→  const fileToBase64 = (file: File): Promise<string> => {
119→    return new Promise((resolve, reject) => {
120→      const reader = new FileReader();
121→      reader.readAsDataURL(file);
122→      reader.onload = () => {
123→        const result = reader.result as string;
124→        // Remove data URL prefix (e.g., "data:application/pdf;base64,")
125→        const base64 = result.split(",")[1];
126→        resolve(base64);
127→      };
128→      reader.onerror = (error) => reject(error);
129→    });
130→  };
131→
132→  const handleProcess = async (selectedFile?: File) => {
133→    const fileToProcess = selectedFile || file;
134→    if (!fileToProcess) return;
135→
136→    setProcessing(true);
137→    setUploadResult(null);
138→    setOcrResult(null);
139→    setCurrentStep("analyze");
140→    // 分析開始時からmarkdownタブを表示
141→    setActiveTab("result");
142→
143→    // Create local URL for preview
144→    const objectUrl = URL.createObjectURL(fileToProcess);
145→    setLocalFileUrl(objectUrl);
146→
147→    try {
148→      const fileType = getFileType(fileToProcess);
149→      if (!fileType) {
150→        throw new Error("Unsupported file format");
151→      }
152→
153→      // Set upload result for preview
154→      setUploadResult({
155→        success: true,
156→        url: objectUrl,
157→        fileType: fileType,
158→      });
159→
160→      // Convert file to base64
161→      const base64Data = await fileToBase64(fileToProcess);
162→
163→      let response;
164→
165→      if (fileType === "pdf") {
166→        // PDF: Upload to S3, process OCR, then delete
167→        response = await processPdfWithMistral(base64Data, fileToProcess.name, true);
168→      } else {
169→        // Image: Process directly with Base64 Data URL (no storage needed)
170→        response = await processImageWithMistral(base64Data, fileToProcess.type, true);
171→      }
172→
173→      if (response.error) {
174→        throw response.error;
175→      }
176→
177→      if (response.result) {
178→        console.log(`${fileType === "pdf" ? t.pdf : t.image} analysis result:`, response.result);
179→        setOcrResult(response.result);
180→        setCurrentStep("result");
181→      }
182→
183→      if (fileInputRef.current) {
184→        fileInputRef.current.value = "";
185→      }
186→    } catch (error) {
187→      console.error("Processing error:", error);
