189→        success: false,
190→        errorMessage: error instanceof Error ? error.message : undefined,
191→      });
192→      setOcrResult({
193→        success: false,
194→        error:
195→          error instanceof Error
196→            ? `${t.analysisError}: ${error.message}`
197→            : t.analysisError,
198→      });
199→    } finally {
200→      setProcessing(false);
201→    }
202→  };
