131→              {page.markdown ? (
132→                <div className="prose prose-sm prose-gray max-w-none text-xs p-1">
133→                <ReactMarkdown
134→                  remarkPlugins={[remarkMath, remarkGfm]}
135→                  rehypePlugins={[rehypeKatex]}
