204→                      const fileName = srcString?.split("/").pop() || "";
205→                      // 現在のページから一致する画像IDを持つ画像を探す
206→                      const matchedImage = page.images?.find((img) => img.id === fileName);
207→
208→                      if (matchedImage?.imageBase64) {
