213→                          <img
214→                            src={base64Src}
215→                            alt={alt || ""}
216→                            className="max-w-full h-auto rounded shadow-sm my-3 mx-auto block"
217→                          />
218→                        );
219→                      }
220→
221→                      // 画像が見つからない場合は元のsrcを使用
222→                      return (
223→                        // eslint-disable-next-line @next/next/no-img-element
224→                        <img
225→                          src={srcString}
226→                          alt={alt || ""}
227→                          className="max-w-full h-auto rounded shadow-sm my-3 mx-auto block"
228→                        />
229→                      );
230→                    },
231→                  }}
232→                >
233→                  {page.markdown}
234→                </ReactMarkdown>
235→              </div>
236→            ) : (
237→              <div className="text-center py-8 text-gray-500">
238→                <svg
239→                  xmlns="http://www.w3.org/2000/svg"
240→                  className="h-12 w-12 mx-auto text-gray-300 mb-3"
241→                  fill="none"
