246→                    strokeLinecap="round"
247→                    strokeLinejoin="round"
248→                    strokeWidth={1.5}
249→                    d="M9.663 17h4.673M12 3v1m6.364 1.636l-.707.707M21 12h-1M4 12H3m3.343-5.657l-.707-.707m2.828 9.9a5 5 0 117.072 0l-.548.547A3.374 3.374 0 0014 18.469V19a2 2 0 11-4 0v-.531c0-.895-.356-1.754-.988-2.386l-.548-.547z"
250→                  />
251→                </svg>
252→                <p>{translations.noTextOnPage}</p>
253→              </div>
254→            )}
255→            {/* ページ番号表示とコピーボタン */}
256→            <div className="flex justify-between items-center px-1 py-1 border-t border-gray-200">
257→              <div className="flex-1"></div>
258→              <span className="text-xs text-gray-500">
259→                {page.index + 1}/{ocrResult.pages.length}
260→              </span>
261→              <div className="flex-1 flex justify-end">
262→                <button
263→                  onClick={() => page.markdown && copyToClipboard(page.markdown, page.index)}
264→                  className="text-gray-500 hover:text-gray-700 transition-colors"
265→                  title={translations.copy}
266→                  disabled={!page.markdown}
267→                >
268→                  {copyingPage === page.index ? (
269→                    <Check className="h-4 w-4 text-green-500" />
270→                  ) : (
271→                    <Copy className="h-4 w-4" />
272→                  )}
273→                </button>
274→              </div>
275→            </div>
276→            </div>
277→            {/* 区切り線 */}
278→            <hr className="border-black my-2" />
279→          </div>
280→        ))}
281→      </div>
282→    </div>
283→  );
284→}
285→
286→// base64データの先頭バイトを確認して画像形式を自動判別
287→const getImageFormat = (base64String: string) => {
288→  try {
289→    // base64データが先頭に「data:image/...;base64,」形式を含む場合は処理
290→    if (base64String.startsWith("data:image/")) {
291→      return base64String;
292→    }
293→
294→    // 先頭バイトからMIMEタイプを判定
295→    const byte = atob(base64String.substring(0, 4));
296→
297→    // 一般的な画像形式のシグネチャ
298→    if (byte.startsWith("\xFF\xD8\xFF")) return `data:image/jpeg;base64,${base64String}`;
299→    if (byte.startsWith("\x89PNG")) return `data:image/png;base64,${base64String}`;
300→    if (byte.startsWith("GIF8")) return `data:image/gif;base64,${base64String}`;
301→    if (byte.startsWith("RIFF")) return `data:image/webp;base64,${base64String}`;
302→
303→    // 判別できない場合はpngとして扱う
304→    return `data:image/png;base64,${base64String}`;
305→  } catch (e) {
306→    console.error("Failed to get image format:", e);
307→    // エラーが発生した場合はpngとして扱う
308→    return `data:image/png;base64,${base64String}`;
309→  }
310→};
311→

