  3→import { Mistral } from "@mistralai/mistralai";
  4→import { OCRResponse } from "@mistralai/mistralai/src/models/components/ocrresponse.js";
  5→import { uploadFileToS3, getS3SignedUrl, deleteFileFromS3 } from "./s3";
  6→
  7→/**
  8→ * Get Mistral client instance
  9→ */
 10→function getMistralClient(): Mistral {
 11→  const apiKey = process.env.MISTRAL_API_KEY;
 12→  if (!apiKey) {
 13→    throw new Error("MISTRAL_API_KEY is not set in environment variables");
 14→  }
 15→  return new Mistral({ apiKey });
 16→}
 17→
 18→/**
 19→ * Process PDF with Mistral OCR (uploads to S3, processes, then deletes)
 20→ * @param fileData Base64 encoded PDF data
 21→ * @param fileName File name
 22→ * @param includeImageBase64 Whether to include Base64 encoded image data
 23→ * @returns OCR processing result
 24→ */
 25→export async function processPdfWithMistral(
 26→  fileData: string,
 27→  fileName: string,
 28→  includeImageBase64: boolean = true
 29→): Promise<{ result: OCRResponse | null; error: Error | null }> {
 30→  let s3Key: string | null = null;
 31→
 32→  try {
 33→    // 1. Upload file to S3
 34→    const uploadResult = await uploadFileToS3(fileData, fileName, "application/pdf");
 35→    if (uploadResult.error) {
 36→      throw uploadResult.error;
 37→    }
 38→    s3Key = uploadResult.key;
 39→
 40→    // 2. Get signed URL from S3
 41→    const signedUrlResult = await getS3SignedUrl(s3Key);
 42→    if (signedUrlResult.error) {
 43→      throw signedUrlResult.error;
 44→    }
 45→
 46→    // 3. Process OCR with Mistral
 47→    const client = getMistralClient();
 48→    const ocrResponse = await client.ocr.process({
 49→      model: "mistral-ocr-latest",
 50→      document: {
 51→        type: "document_url",
 52→        documentUrl: signedUrlResult.url,
 53→      },
 54→      includeImageBase64,
 55→    });
 56→
 57→    return { result: ocrResponse, error: null };
 58→  } catch (error) {
 59→    console.error("Error occurred during PDF OCR processing:", error);
 60→    return {
 61→      result: null,
 62→      error: error instanceof Error ? error : new Error("An unknown error occurred"),
 63→    };
 64→  } finally {
 65→    // 4. Clean up: Delete file from S3
 66→    if (s3Key) {
 67→      try {
 68→        await deleteFileFromS3(s3Key);
 69→      } catch (deleteError) {
 70→        console.error("Failed to delete file from S3:", deleteError);
 71→      }
 72→    }
 73→  }
 74→}
 75→
 76→/**
 77→ * Process image with Mistral OCR using Base64 Data URL (no storage needed)
 78→ * @param imageData Base64 encoded image data
 79→ * @param mimeType Image MIME type (e.g., 'image/png', 'image/jpeg')
 80→ * @param includeImageBase64 Whether to include Base64 encoded image data
 81→ * @returns OCR processing result
 82→ */
 83→export async function processImageWithMistral(
 84→  imageData: string,
 85→  mimeType: string,
 86→  includeImageBase64: boolean = true
 87→): Promise<{ result: OCRResponse | null; error: Error | null }> {
 88→  try {
 89→    const client = getMistralClient();
 90→    const dataUrl = `data:${mimeType};base64,${imageData}`;
 91→
 92→    const ocrResponse = await client.ocr.process({
 93→      model: "mistral-ocr-latest",
 94→      document: {
 95→        type: "image_url",
 96→        imageUrl: dataUrl,
 97→      },
 98→      includeImageBase64,
 99→    });
100→
101→    return { result: ocrResponse, error: null };
102→  } catch (error) {
103→    console.error("Error occurred during image OCR processing:", error);
104→    return {
105→      result: null,
106→      error: error instanceof Error ? error : new Error("An unknown error occurred"),
107→    };
108→  }
109→}
